"""Tests for hairsetup.py: the implicit setup on the first applied asset, and cleaning up after a loaded asset."""

import bpy
import pytest

from ... import ObjectService
from .haireditor_fixtures import (hairsetup, HAIR_PROPERTIES, scratch, character, select, link, make_grid,
                                  make_material)


def _curves_children(basemesh):
    return [child for child in ObjectService.get_list_of_children(basemesh) if child.type == "CURVES"]


def test_nothing_is_set_up_to_begin_with(character):
    assert not hairsetup.is_hair_setup(None)
    assert not hairsetup.is_hair_setup(character)


def test_setup_runs_once(character):
    assert hairsetup.ensure_hair_setup(character, bpy.context)
    assert hairsetup.is_hair_setup(character)
    assert HAIR_PROPERTIES.get_value("hair_setup", False, entity_reference=character)
    assert len(_curves_children(character)) == 1, "the empty hair object the assets need"
    assert bpy.context.view_layer.objects.active == character

    assert not hairsetup.ensure_hair_setup(character, bpy.context), "the second asset must not repeat the setup"
    assert len(_curves_children(character)) == 1


def test_setup_is_redone_when_its_curves_are_gone(character):
    """The flag is saved with the file, but the user can delete the hair object it stands for."""
    hairsetup.ensure_hair_setup(character, bpy.context)
    for child in _curves_children(character):
        bpy.data.objects.remove(child, do_unlink=True)
    assert not hairsetup.is_hair_setup(character)
    assert hairsetup.ensure_hair_setup(character, bpy.context)
    assert len(_curves_children(character)) == 1


def test_eevee_renders_the_hair_as_strips(character):
    scene = bpy.context.scene
    engines = {item.identifier for item in scene.render.bl_rna.properties['engine'].enum_items}
    eevee = next((engine for engine in ("BLENDER_EEVEE_NEXT", "BLENDER_EEVEE") if engine in engines), None)
    if eevee is None or not hasattr(scene.render, "hair_type"):
        pytest.skip("No EEVEE hair settings in this blender")
    engine, hair_type = scene.render.engine, scene.render.hair_type
    try:
        scene.render.engine = eevee
        scene.render.hair_type = 'STRAND'
        hairsetup.ensure_hair_setup(character, bpy.context)
        assert scene.render.hair_type == 'STRIP'
    finally:
        scene.render.engine = engine
        scene.render.hair_type = hair_type


def test_unused_images_from_the_asset_are_discarded(scratch):
    existing = bpy.data.images.new("setup_existing_unused", 4, 4)
    before = hairsetup.list_image_names()
    assert existing.name in before

    orphan = bpy.data.images.new("setup_orphan", 4, 4)
    orphan_name = orphan.name
    protected = bpy.data.images.new("setup_fake_user", 4, 4)
    protected.use_fake_user = True
    used = bpy.data.images.new("setup_used", 4, 4)
    material = make_material("setup_uses_an_image")
    material.node_tree.nodes.new('ShaderNodeTexImage').image = used

    hairsetup.discard_unused_images(before)
    assert orphan_name not in bpy.data.images
    assert protected.name in bpy.data.images
    assert used.name in bpy.data.images
    assert existing.name in bpy.data.images, "only images the asset brought along are touched"


def test_only_hair_curves_can_be_attached(scratch):
    body = make_grid("setup_attach_body")
    not_hair = make_grid("setup_attach_not_hair")
    assert not hairsetup.attach_curves_to_basemesh(not_hair, body)


def test_curves_without_a_surface_are_attached(scratch):
    body = make_grid("setup_attach_body_plain")
    hair_obj = link(bpy.data.objects.new("setup_attach_hair", bpy.data.hair_curves.new("setup_attach_hair")))
    assert hairsetup.attach_curves_to_basemesh(hair_obj, body)
    assert hair_obj.data.surface == body


def test_surface_brought_along_by_the_asset_is_thrown_away(scratch):
    """Assets are stored with the character they were groomed on, which would otherwise pile up in the file."""
    body = make_grid("setup_new_body")
    groomed_on_mesh = bpy.data.meshes.new("setup_groomed_on")
    groomed_on_mesh.materials.append(make_material("setup_groomed_on_skin"))
    groomed_on = bpy.data.objects.new("setup_groomed_on", groomed_on_mesh)  # Loaded, but not in any collection
    hair_obj = link(bpy.data.objects.new("setup_attach_hair_loaded", bpy.data.hair_curves.new("setup_loaded")))
    hair_obj.data.surface = groomed_on

    assert hairsetup.attach_curves_to_basemesh(hair_obj, body)
    assert hair_obj.data.surface == body
    assert "setup_groomed_on" not in bpy.data.objects
    assert "setup_groomed_on" not in bpy.data.meshes
    assert "setup_groomed_on_skin" not in bpy.data.materials


def test_surface_in_the_scene_is_kept(scratch):
    body = make_grid("setup_new_body_kept")
    in_scene = make_grid("setup_surface_in_scene")
    hair_obj = link(bpy.data.objects.new("setup_attach_hair_kept", bpy.data.hair_curves.new("setup_kept")))
    hair_obj.data.surface = in_scene
    assert hairsetup.attach_curves_to_basemesh(hair_obj, body)
    assert "setup_surface_in_scene" in bpy.data.objects


def test_attaching_to_the_same_surface_again(scratch):
    body = make_grid("setup_same_body")
    hair_obj = link(bpy.data.objects.new("setup_attach_hair_same", bpy.data.hair_curves.new("setup_same")))
    hair_obj.data.surface = body
    assert hairsetup.attach_curves_to_basemesh(hair_obj, body)
    assert "setup_same_body" in bpy.data.objects
